'use strict';
const KEY='hoshimimi-v1';
const defs=[['月あかり茶屋','🍵',12,1,2,'チャイ'],['雲のパン工房','🥐',140,8,4,'コムギ'],['星糸の仕立て屋','🧵',1700,65,7,'イト'],['流星郵便局','✉️',21000,540,10,'ポスト'],['夜空の温室','🌱',270000,4600,14,'モス'],['銀河の灯台','🔭',3500000,40000,20,'ルーメン']];
const fresh=()=>({v:1,money:12,total:0,stars:0,shops:defs.map(()=>({n:0,auto:false,p:0})),ups:[],at:Date.now()});
let s=fresh(),tab='shops',quantity=1,last=Date.now(),offline=0;
function valid(a){return a&&a.v===1&&Number.isFinite(a.money)&&a.money>=0&&Number.isFinite(a.total)&&a.total>=0&&Number.isInteger(a.stars)&&a.stars>=0&&a.stars<1e9&&Array.isArray(a.shops)&&a.shops.length===6&&a.shops.every(x=>Number.isInteger(x.n)&&x.n>=0&&x.n<=10000&&typeof x.auto==='boolean'&&Number.isFinite(x.p)&&x.p>=0)&&Array.isArray(a.ups)&&a.ups.every(x=>Number.isInteger(x)&&x>=0&&x<4)&&Number.isFinite(a.at)}
try{let a=JSON.parse(localStorage.getItem(KEY));if(valid(a))s=a}catch{}
const $=x=>document.getElementById(x);const fmt=n=>{if(n<10000)return Math.floor(n).toLocaleString('ja-JP');for(const [v,u]of [[1e24,'秭'],[1e20,'垓'],[1e16,'京'],[1e12,'兆'],[1e8,'億'],[1e4,'万']])if(n>=v)return(n/v).toFixed(2)+u;return n.toExponential(2)};
const multiplier=()=> (1+s.stars*.1)*Math.pow(2,s.ups.length);
const value=i=>defs[i][3]*s.shops[i].n*Math.pow(2,Math.floor(s.shops[i].n/25))*multiplier();
const cost=(i,n=quantity)=>{const q=s.shops[i].n;return Math.ceil(defs[i][2]*Math.pow(1.13,q)*(Math.pow(1.13,n)-1)/.13-1e-8)};
const autoCost=i=>defs[i][2]*8;const rate=()=>s.shops.reduce((a,x,i)=>a+(x.auto?value(i)/defs[i][4]:0),0);
function gain(n){if(Number.isFinite(n)&&n>0){s.money=Math.min(1e290,s.money+n);s.total=Math.min(1e290,s.total+n)}}
function advance(seconds,off=false){s.shops.forEach((x,i)=>{if(!x.n||(!x.auto&&(off||!x.p)))return;const d=defs[i][4];if(x.auto){const t=x.p+seconds;gain(Math.floor(t/d)*value(i));x.p=t%d}else{x.p+=seconds;if(x.p>=d){gain(value(i));x.p=0}}})}
offline=Math.min(28800,Math.max(0,(Date.now()-s.at)/1000));const before=s.money;advance(offline,true);const away=s.money-before;
function save(){s.at=Date.now();try{localStorage.setItem(KEY,JSON.stringify(s));$('save').textContent='保存済み ✓'}catch{$('save').textContent='保存できません'}}
let timer;function toast(t){$('toast').textContent=t;$('toast').style.display='block';clearTimeout(timer);timer=setTimeout(()=>$('toast').style.display='none',3500)}
function buy(i){const c=cost(i);if(s.money+1e-8<c||s.shops[i].n+quantity>10000)return;s.money=Math.max(0,s.money-c);s.shops[i].n+=quantity;save();render()}
function hire(i){if(s.shops[i].auto||!s.shops[i].n||s.money<autoCost(i))return;s.money-=autoCost(i);s.shops[i].auto=true;save();toast(defs[i][5]+'が仲間に！ 自動経営がはじまった');render()}
const upgradeCosts=[1000,50000,2500000,100000000];
function upgrade(i){if(s.ups.includes(i)||s.money<upgradeCosts[i])return;s.money-=upgradeCosts[i];s.ups.push(i);save();render()}
function render(){let html='';if(tab==='shops'){html='<div class="status-row"><span>✦ 6つのお店を育てよう</span><span>☾ おまかせ経営で夜も成長</span></div><div class="toolbar"><div><b>灯りをひとつずつ。</b><br><small>25店舗ごとに売上2倍</small></div><div>'+[1,10,25].map(n=>`<button class="pill" data-q="${n}" style="opacity:${quantity===n?1:.5}">×${n}</button>`).join('')+'</div></div>';html+=defs.map((d,i)=>{const x=s.shops[i];return `<article class="shop ${x.auto?'auto':''}"><div class="icon portrait p${i}" role="img" aria-label="${d[5]}"></div><div><h3>${d[0]} <small>Lv.${x.n}</small></h3><small>${fmt(value(i))} 星くず / ${d[4]}秒</small><div class="bar"><div class="fill" id="progress${i}" style="width:${x.p/d[4]*100}%"></div></div><button class="manager" data-run="${i}" ${!x.n||x.auto?'disabled':''}>${x.auto?'✓ '+d[5]+'が経営中':x.p?'準備中…':'▶ お店を動かす'}</button><br><button class="manager" data-hire="${i}" ${!x.n||x.auto||s.money<autoCost(i)?'disabled':''}>${x.auto?'自動化済み':'店員を雇う · '+fmt(autoCost(i))}</button></div><button class="gold buy" data-buy="${i}" ${s.money<cost(i)||x.n+quantity>10000?'disabled':''}>${x.n?'増設':'開店'} ×${quantity}<br>✦ ${fmt(cost(i))}</button></article>`}).join('')}
if(tab==='upgrades'){html='<h2>小さな発明、大きな売上。</h2><p class="muted">研究はすべてのお店に効きます。</p>'+['星明かりの看板','雲の配達カート','星座の案内図','銀河の物流網'].map((n,i)=>`<div class="panel"><h3>${n}</h3><p>すべてのお店の売上 ×2</p><button class="gold" data-up="${i}" ${s.ups.includes(i)||s.money<upgradeCosts[i]?'disabled':''}>${s.ups.includes(i)?'研究済み':'研究する · '+fmt(upgradeCosts[i])}</button></div>`).join('');const stars=Math.floor(Math.sqrt(s.total/1e6));html+=`<div class="panel"><h3>次の空へ</h3><p>今の想い出の星：${s.stars}<br>今回の旅で獲得：${stars}個<br>累計売上100万で1個。1個ごとに次の旅の売上+10%。</p><button class="gold" id="prestige" ${stars<1?'disabled':''}>旅立ちの準備</button></div>`}
if(tab==='story'){const chapters=[[0,'01 · 灯りのない商店街','「この街に、もう一度星を灯したいんだ」見習い店長ミモは、古い茶屋の鍵をあなたに託した。'],[1000,'02 · パンの香る朝','焼きたての香りに誘われ、コムギがやってきた。「お留守番はまかせて。眠っている間も、街をあたためるよ」'],[50000,'03 · 遠い星への手紙','ポストが運んだ手紙には、まだ見ぬ街からの注文が。「ひとつの灯りが、遠くまで届いたんだね」'],[1000000,'04 · 星をつなぐ約束','丘の灯台に光が戻った。ミモはあなたの隣で、小さな地図を広げる。「次の空でも、一緒にお店を開こう」']];html='<h2>星くずでつづる、あなたの物語。</h2>'+chapters.map(([n,t,p])=>`<article class="panel"><div class="chapter-art ${s.total>=n?'':'locked'}"></div><small>${s.total>=n?'解放済み':'累計売上 '+fmt(n)+' で解放'}</small><h3>${t}</h3><p>${s.total>=n?p:'まだ白紙のページ。お店を育てると、つづきが届きます。'}</p></article>`).join('')+'<div class="panel"><h3>商店街の仲間たち</h3><p>ミモ：星柄エプロンの見習い店長<br>コムギ：パン作りが好きなねこ<br>イト：寡黙で手先の器用な仕立て屋<br>ポスト：遠い街をつなぐ配達員</p></div>'}
if(tab==='settings')html='<h2>旅のしおり</h2><div class="panel"><h3>セーブデータ</h3><p>自動保存は5秒ごと。ブラウザのデータ削除で進行が消えるため、ときどき書き出してください。</p><div class="actions"><button class="gold" id="export">セーブを書き出す</button><label class="pill">読み込む<input id="import" type="file" accept="application/json" hidden></label></div></div><div class="panel"><h3>この試作版について</h3><p>独自制作のキャラクター・文章・CSSイラストを使用。広告、課金、ガチャ、チャット、ランキング、アクセス解析はありません。ゲームの進行は端末内で保存し、ゲームから外部送信しません。配信サイト側の認証や通信は別途そのサービスの規約に従います。</p><p>名称は仮称です。正式公開前に商標などの確認が必要です。審査通過や法令への完全適合を保証するものではありません。</p></div>';
if(tab==='story')html+='<h2>商店街の店員図鑑</h2><div class="crew">'+defs.map((d,i)=>'<div class="crew-card"><div class="portrait p'+i+'" role="img" aria-label="'+d[5]+'"></div><b>'+d[5]+'</b><small>'+d[0]+'</small></div>').join('')+'</div>'; $('content').innerHTML=html;
document.querySelectorAll('[data-q]').forEach(b=>b.onclick=()=>{quantity=+b.dataset.q;render()});document.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>buy(+b.dataset.buy));document.querySelectorAll('[data-hire]').forEach(b=>b.onclick=()=>hire(+b.dataset.hire));document.querySelectorAll('[data-run]').forEach(b=>b.onclick=()=>{const x=s.shops[+b.dataset.run];if(!x.p)x.p=.001;render()});document.querySelectorAll('[data-up]').forEach(b=>b.onclick=()=>upgrade(+b.dataset.up));if($('prestige'))$('prestige').onclick=()=>$('confirm').showModal();if($('export'))$('export').onclick=()=>{save();if(window.webkit?.messageHandlers?.exportSave){window.webkit.messageHandlers.exportSave.postMessage(JSON.stringify(s));return}const u=URL.createObjectURL(new Blob([JSON.stringify(s)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download='hoshimimi-save.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};if($('import'))$('import').onchange=async e=>{try{const f=e.target.files[0];if(!f||f.size>100000)throw Error();const a=JSON.parse(await f.text());if(!valid(a))throw Error();s=a;s.at=Date.now();last=Date.now();save();render();toast('セーブを読み込みました')}catch{toast('このセーブは読み込めません')}};hud()}
function hud(){document.querySelector('.world').dataset.stage=s.total>=1e6?'4':s.total>=50000?'3':s.total>=1000?'2':'1';$('worldStage').textContent=s.total>=1e6?'第4夜 · 星をつなぐ約束':s.total>=50000?'第3夜 · 遠い星への手紙':s.total>=1000?'第2夜 · パンの香る朝':'第1夜 · はじまりの灯り';$('worldCaption').textContent=s.shops.filter(x=>x.n>0).length+' / 6 店舗が開店 · '+s.shops.filter(x=>x.auto).length+' 人の仲間がお仕事中';$('money').textContent=fmt(s.money);$('rate').textContent='✦ '+fmt(rate())+' / 秒（自動）';const q=[[1000,'累計1,000星くずを届ける'],[50000,'累計5万星くずを届ける'],[1e6,'累計100万で次の空へ']].find(x=>s.total<x[0]);$('quest').textContent=q?q[1]:'銀河へ灯りを届けよう';$('questProgress').textContent='累計売上 '+fmt(s.total)+' ✦';$('tap').textContent='✦ お届けする +'+fmt(Math.max(1,rate()*.1));$('hint').textContent=s.shops.some(x=>x.auto)?'お店の灯りが増えてきたね。研究室でもっと遠くへ届けよう。':'まずは茶屋を開店して「お店を動かす」を押そう。店員を雇うと自動になるよ。';s.shops.forEach((x,i)=>{const b=$('progress'+i);if(b)b.style.width=x.p/defs[i][4]*100+'%'});document.querySelectorAll('[data-buy]').forEach(b=>b.disabled=s.money<cost(+b.dataset.buy)||s.shops[+b.dataset.buy].n+quantity>10000);document.querySelectorAll('[data-hire]').forEach(b=>{const i=+b.dataset.hire;b.disabled=!s.shops[i].n||s.shops[i].auto||s.money<autoCost(i)});document.querySelectorAll('[data-up]').forEach(b=>b.disabled=s.ups.includes(+b.dataset.up)||s.money<upgradeCosts[+b.dataset.up]);document.querySelectorAll('[data-run]').forEach(b=>{const i=+b.dataset.run,x=s.shops[i];b.textContent=x.auto?'✓ '+defs[i][5]+'が経営中':x.p?'準備中…':'▶ お店を動かす'});if($('prestige'))$('prestige').disabled=s.total<1e6}
$('tap').onclick=e=>{const n=Math.max(1,rate()*.1);gain(n);hud();const p=document.createElement('span');p.className='float-gain';p.textContent='✦ +'+fmt(n);p.style.left=(e.clientX||innerWidth/2)+'px';p.style.top=(e.clientY||innerHeight/2)+'px';document.body.appendChild(p);setTimeout(()=>p.remove(),950)};$('save').onclick=()=>{save();toast($('save').textContent)};document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('active',x===b));render()});$('reincarnate').onclick=()=>{const n=Math.floor(Math.sqrt(s.total/1e6));if(n<1)return;const stars=s.stars+n;s=fresh();s.stars=stars;$('confirm').close();save();render();toast('新しい空へ！ 想い出の星 +'+n)};
setInterval(()=>{const now=Date.now();advance(Math.min(28800,Math.max(0,(now-last)/1000)),document.hidden);last=now;hud()},200);setInterval(save,5000);document.addEventListener('visibilitychange',()=>{if(document.hidden)save()});window.addEventListener('pagehide',save);render();save();if(away>0)toast('おかえり！ 留守中の売上 +'+fmt(away)+' 星くず');
